import raw from "./echo.json";

// Live verification results: each run impersonates a record, asks
// tls.peet.ws to echo the ClientHello back, and compares it with the capture the
// record was built from. Generated by scripts/sync-echo.mjs from
// goal-evidence/echo-latest.

export interface EchoRun {
  name: string;
  status: string;
  httpVersion: string;
  userAgent: string;
  captureJa4: string;
  echoJa4: string;
  captureExtensions: number;
  echoExtensions: number;
  /** Capture extensions the live handshake did not send (GREASE excluded). */
  missing: string[];
  /** Live extensions the capture did not have. */
  extra: string[];
  akamaiCapture: string;
  akamaiEcho: string;
}

const dataset = raw as unknown as { generatedFrom: string; runs: EchoRun[] };

export const echoRuns = dataset.runs;

/**
 * How the live handshake compares with the capture, segment by segment:
 * - identical: all of JA4 matches.
 * - ciphers: the a-segment's counts and the b-segment (ciphers + extensions)
 *   match, only the c-segment (signature algorithms + SNI) differs. That is
 *   what ML-DSA and signature-algorithm GREASE cost, and the server still
 *   sees the same cipher/extension shape.
 * - differs: the cipher/extension hash differs too.
 */
export function verdict(run: EchoRun): "identical" | "ciphers" | "differs" {
  if (run.echoJa4 === run.captureJa4) return "identical";
  const [, b1] = run.echoJa4.split("_");
  const [, b2] = run.captureJa4.split("_");
  // Same cipher/extension hash means the server cannot tell the two apart by
  // what the ciphers and extensions are; only the sigalg hash moved.
  return b1 && b1 === b2 ? "ciphers" : "differs";
}

/** The per-segment comparison, for the panel's marks. */
export function segments(run: EchoRun): { capture: string; echo: string; same: boolean }[] {
  const capture = run.captureJa4.split("_");
  const echo = run.echoJa4.split("_");
  return capture.map((value, index) => ({
    capture: value,
    echo: echo[index] ?? "",
    same: value === (echo[index] ?? ""),
  }));
}
